#include "scarlett_imports64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;ScarlettImports64 h;assert(h.install(m));assert(m.map(0x10000,4096,3)==GuestMemory64::Fault::none);auto put=[&](uint64_t a,std::initializer_list<uint8_t> b){assert(m.write(a,std::vector<uint8_t>(b))==GuestMemory64::Fault::none);};put(0x10000,{'%','d',0});put(0x10100,{42,0,0,0,0,0,0,0});uint64_t r=0;auto call=[&](const char* n,uint64_t cap,uint64_t fmt,uint64_t a5,uint64_t a6,uint64_t a7=0){auto a=h.registerImport("api-ms-win-crt-stdio-l1-1-0.dll",n);assert(a&&h.dispatch(a,m,0,r,0x10200,cap,fmt,a5,a6,nullptr,a7));};auto check=[&](std::initializer_list<uint8_t> expected){std::vector<uint8_t>b(expected.size());assert(m.read(0x10200,b)==GuestMemory64::Fault::none);assert(b==std::vector<uint8_t>(expected));};call("__stdio_common_vsprintf_s",8,0x10000,0,0x10100);assert(r==2);check({'4','2',0});call("__stdio_common_vsprintf_s",2,0x10000,0,0x10100);assert(r==UINT32_MAX);check({0});call("__stdio_common_vsnprintf_s",2,UINT64_MAX,0x10000,0,0x10100);assert(r==UINT32_MAX);check({'4',0});put(0x10000,{'%',0,'d',0,0,0});call("__stdio_common_vswprintf_s",8,0x10000,0,0x10100);assert(r==2);check({'4',0,'2',0,0,0});std::cout<<"V85C formatting tests passed\n";}
